  evolucaoModa: string;
  evolucaoModaCount: number;
  vacinaUTI: CrossTabCell[];
  vacinaSimUTI: number;
  vacinaNaoUTI: number;
  boxPlotData: BoxPlotData[];
  // Dashboard interativo
